from "dialects/hlo.tepl" import HLO as hlo;

// Expression check under the source conditions recorded in the catalog.
rule expr_slice_reverse_general {
    X: [Dims...] (attr_s: hlo.slice (attr_r: hlo.reverse X)) => (axis_eval_0: hlo.reverse (attr_out: hlo.slice X)) where { all([n > 0 for n in attr_s.attrs.sizes]) } 
derive {
 attr_out.attrs = {starts: [if contains(attr_r.attrs.dimensions, i) then i64(Dims[i] - 1 - (u64(attr_s.attrs.starts[i]) + (attr_s.attrs.sizes[i] - 1) * u64(attr_s.attrs.strides[i]))) else attr_s.attrs.starts[i] for i in range(len(Dims))], sizes: attr_s.attrs.sizes, strides: attr_s.attrs.strides};
 axis_eval_0.attrs = {dimensions: auto};
}
}

// Canonical axis-only evaluation task; no descriptor or non-axis inference.
from "dialects/hlo.tepl" import HLO as hlo;

// One spatial dimension; kernel and output feature axes are last.
rule expr_convolution_scale_filter_bias {
    X: [N, H, C]
    W: [KW, C, F]
    Bias: [N, O, F]
    Scale: [F]
    (hlo.multiply (hlo.add (attr_conv: hlo.convolution X W) Bias) (attr_output: hlo.broadcast Scale)) => (hlo.add (axis_eval_0: hlo.convolution X (hlo.multiply W (attr_kernel: hlo.broadcast Scale))) (hlo.multiply Bias (axis_eval_1: hlo.broadcast Scale)))
    where { attr_output.attrs.dimensions == [2] && attr_output.attrs.new_extents == [N, O] }

derive {
 attr_kernel.attrs = {dimensions: auto, new_extents: [KW, C]};
 axis_eval_0.attrs = {strides: attr_conv.attrs.strides, dilations: attr_conv.attrs.dilations};
 axis_eval_1.attrs = {dimensions: auto, new_extents: attr_output.attrs.new_extents};
}
}

// Canonical axis-only evaluation task; no descriptor or non-axis inference.
from "dialects/hlo.tepl" import HLO as hlo;

// Catalog: broadcast-slice-broadcast-only
// Scope: Rank-one X maps to axis zero; only newly created axes are sliced.
// Source arithmetic/applicability conditions are recorded in the manifest.
rule catalog_broadcast_slice_broadcast_only {
    X: [N]
     (attr_s: hlo.slice (attr_b: hlo.broadcast X)) => (attr_out: hlo.broadcast X)
     where { attr_b.attrs.dimensions == [0] && attr_s.attrs.starts[0]==0 && attr_s.attrs.sizes[0]==N && attr_s.attrs.strides[0]==1 }

derive {
 attr_out.attrs = {dimensions: auto, new_extents: slice(attr_s.attrs.sizes,1,len(attr_s.attrs.sizes))};
}
}

// Canonical axis-only evaluation task; no descriptor or non-axis inference.
from "dialects/hlo.tepl" import HLO as hlo;

// Catalog: broadcast-slice-broadcast
// Scope: Arbitrary tensor shapes under the catalog arithmetic/applicability assumptions.
// Source arithmetic/applicability conditions are recorded in the manifest.
rule catalog_broadcast_slice_broadcast {
    X: [Dims...]
     (attr_s: hlo.slice (attr_b: hlo.broadcast X)) => (attr_out: hlo.broadcast (attr_inner: hlo.slice X))

derive {
 attr_inner.attrs = {starts: gather(attr_s.attrs.starts,attr_b.attrs.dimensions), sizes: gather(attr_s.attrs.sizes,attr_b.attrs.dimensions), strides: gather(attr_s.attrs.strides,attr_b.attrs.dimensions)};
 attr_out.attrs = {dimensions: auto, new_extents: gather(attr_s.attrs.sizes,exclude(range(len(attr_s.attrs.sizes)),attr_b.attrs.dimensions))};
}
}

// Canonical axis-only evaluation task; no descriptor or non-axis inference.
from "dialects/hlo.tepl" import HLO as hlo;

// Catalog: indexing-slice-singleton-stride
// Scope: Arbitrary tensor shapes under the catalog arithmetic/applicability assumptions.
// Source arithmetic/applicability conditions are recorded in the manifest.
rule catalog_indexing_slice_singleton_stride {
    (attr_s: hlo.slice X) => (attr_out: hlo.slice X)

derive {
 attr_out.attrs = {starts: attr_s.attrs.starts, sizes: attr_s.attrs.sizes, strides: [if attr_s.attrs.sizes[i]<=1 then 1 else attr_s.attrs.strides[i] for i in range(len(attr_s.attrs.sizes))]};
}
}

// Canonical axis-only evaluation task; no descriptor or non-axis inference.
from "dialects/hlo.tepl" import HLO as hlo;

// Catalog: dot-slice-output
// Scope: Rank-two dot with arbitrary output starts, sizes and positive strides.
// Source arithmetic/applicability conditions are recorded in the manifest.
rule catalog_dot_slice_output {
    X: [M,K] Y: [K,N]
     (attr_s: hlo.slice (attr_d: hlo.dot X Y)) => (axis_eval_0: hlo.dot (attr_left: hlo.slice X) (attr_right: hlo.slice Y))
     where { attr_d.attrs.lhs_batching_dimensions==[] && attr_d.attrs.rhs_batching_dimensions==[] && attr_d.attrs.lhs_contracting_dimensions==[1] && attr_d.attrs.rhs_contracting_dimensions==[0] }

derive {
 attr_left.attrs = {starts: [attr_s.attrs.starts[0],0], sizes: [attr_s.attrs.sizes[0],K], strides: [attr_s.attrs.strides[0],1]};
 attr_right.attrs = {starts: [0,attr_s.attrs.starts[1]], sizes: [K,attr_s.attrs.sizes[1]], strides: [1,attr_s.attrs.strides[1]]};
 axis_eval_0.attrs = {lhs_contracting_dimensions: auto, rhs_contracting_dimensions: auto, lhs_batching_dimensions: auto, rhs_batching_dimensions: auto};
}
